INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es in der IT nur einen Markt gibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Verschiedene Marktarten existieren"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Marktarten für eine IT-Firma analysiere?', 3, '[{"text": "Zielgruppenbedarf", "correct": true, "because": "Bestimmt Relevanz"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Marktarten gibt es im IT-Kontext?', 5, '[{"text": "B2B-Markt", "correct": true, "because": "Business-to-Business"}, {"text": "B2C-Markt", "correct": true, "because": "Business-to-Consumer"}, {"text": "Büromöbelmarkt", "correct": false, "because": "Kein IT-Markt"}, {"text": "Farbenmarkt", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) B2B-Märkte richten sich an Unternehmen. b) Alle IT-Märkte sind gleich groß.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größe variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Marktarten für eine IT-Strategie analysiere?', 4, '[{"text": "Kundenbedürfnisse", "correct": false, "because": "Bestimmen Fokus"}, {"text": "Wettbewerber", "correct": false, "because": "Beeinflussen Markt"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marktarten nur lokal relevant sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch global möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Marktarten in der IT analysiere?', 3, '[{"text": "Marktchancen erkennen", "correct": true, "because": "Fördert Strategie"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kategorien von Marktarten sind für IT-Firmen wichtig?', 5, '[{"text": "Zielmärkte", "correct": true, "because": "Definieren Kunden"}, {"text": "Absatzmärkte", "correct": true, "because": "Bestimmen Vertrieb"}, {"text": "Büromärkte", "correct": false, "because": "Kein IT-Fokus"}, {"text": "Designmärkte", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Nischenmärkte sind eine Marktart in der IT. b) Alle Marktarten sind gleich profitabel. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Profit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Marktarten für eine IT-Firma zu analysieren?', 4, '[{"text": "Marktdaten", "correct": false, "because": "Grundlage der Analyse"}, {"text": "Kundenprofile", "correct": false, "because": "Bestimmen Zielgruppen"}, {"text": "Bürofarben", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Marktarten in der IT immer global?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Analyse von Marktarten?', 4, '[{"text": "Wettbewerbsvorteil", "correct": true, "because": "Passt Strategie an"}, {"text": "Marktchancen", "correct": true, "because": "Zeigt Potenziale"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marktarten nur für Hardware relevant sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Software/Dienste"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Marktarten für eine IT-Strategie zu bestimmen?', 3, '[{"text": "Marktforschung", "correct": true, "because": "Liefert Daten"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) B2C-Märkte richten sich an Endkunden. b) Alle Marktarten sind gleich groß.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Größe variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Marktarten in der IT?', 5, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Bestimmen Nachfrage"}, {"text": "Wettbewerber", "correct": true, "because": "Beeinflussen Markt"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Marktarten für eine IT-Firma analysiere?', 3, '[{"text": "Marktgröße", "correct": false, "because": "Bestimmt Potenzial"}, {"text": "Kundensegmente", "correct": false, "because": "Definieren Zielgruppen"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Marktfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Marktarten immer statisch?', 3, '[{"text": "Nein", "correct": true, "because": "Ändern sich dynamisch"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marktarten nur für Produkte relevant sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Dienstleistungen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um Marktarten zu analysieren?', 4, '[{"text": "Marktdaten", "correct": true, "because": "Liefern Grundlage"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
